def save_clinvar_benchmark(out_path="data/processed/clinvar_benchmark_sample.csv"):
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    df = pd.DataFrame(CLINICAL_VARIANTS)
    df.to_csv(out_path, index=False)
    print(f"Curated {len(df)} validated ClinVar gold-standard clinical variants to {out_path}")
    return df

if __name__ == "__main__":
    save_clinvar_benchmark()
